#!/usr/bin/env bash
# Generated by build.sh from src-5af57c8ce9 - do not edit, edit src/ and rebuild.
GM_BUILD=src-5af57c8ce9

# ==== src/lib/00-base.sh ====
# shellcheck shell=bash
# 00-base.sh - shared globals, temp dir, traps, fatal errors (start-up problems only).
#
# Library rules (all files in src/lib):
#   * no `set -e` here. The entry file decides shell options. Actions get errexit from act_run.
#   * everything must be `set -u` clean.
#   * return data through variables named by the caller (namerefs) or through stdout, never
#     through hidden globals that another screen might overwrite.

if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 3))); then
  echo "bash 4.3 or newer is required (this is $BASH_VERSION)" >&2
  exit 1
fi
shopt -s extglob

GM_APP=${GM_APP:-gemini-menu}
GM_VERSION=${GM_VERSION:-0.1.0-phase1}
GM_DRY=${GM_DRY:-0}          # 1 = dry-run: actions describe instead of change
GM_YES=${GM_YES:-0}          # 1 = --yes: plain confirmations are auto-accepted
GM_INT=0                     # set to 1 by the SIGINT handler (Ctrl-C) in the main shell
GM_TMP=""

# Fatal error for *programming / start-up* mistakes only (bad menu definition, no terminal).
# Runtime problems inside actions must use act_fail / return codes instead.
gm_fatal() {
  printf 'fatal: %s\n' "$*" >&2
  exit 1
}

gm_tmp_init() {
  if [[ -z $GM_TMP || ! -d $GM_TMP ]]; then
    GM_TMP=$(mktemp -d "${TMPDIR:-/tmp}/gm.XXXXXX") || gm_fatal "cannot create a temporary directory"
  fi
}

# Runs in the MAIN shell on exit. Subshells (actions) have their own EXIT trap and never run this.
gm_on_exit() {
  ui_task_cleanup 2>/dev/null || true
  if [[ -t 0 ]]; then stty sane 2>/dev/null || true; fi
  if [[ -n $GM_TMP && -d $GM_TMP ]]; then rm -rf "$GM_TMP"; fi
}

# Ctrl-C in the main shell never exits the program. It raises a flag that a spinner notices, and
# while a prompt is waiting it prints a hint right away: `read -e` does NOT return on Ctrl-C (bash
# runs the trap mid-read and readline keeps the half-typed line), so the hint has to come from
# the handler itself. `q` is the way out.
GM_READING=0
gm_on_int() {
  GM_INT=1
  if ((GM_READING)); then
    printf '\n  %sCtrl-C does not quit the menu - type q to quit, b to go back.%s\n' "${C_DIM:-}" "${C_0:-}"
  fi
}

gm_install_traps() {
  trap gm_on_int INT
  trap 'exit 143' TERM
  trap gm_on_exit EXIT
}

is_dry() { [[ $GM_DRY == 1 ]]; }

# ==== src/lib/10-term.sh ====
# shellcheck shell=bash
# 10-term.sh - terminal capabilities, palette, glyph sets and width helpers.
#
# Text that is shown inside boxes is measured with ui_vlen, which ignores colour escapes.
# Wide (East-Asian / emoji) characters are NOT measured: keep user data out of boxes or pass it
# through ui_safe first. The UI itself only uses narrow glyphs.

UI_TTY=0 UI_COLOR=0 UI_UNICODE=0 UI_W=78

ui_detect() {
  if [[ -t 1 ]]; then UI_TTY=1; else UI_TTY=0; fi

  UI_COLOR=0
  if ((UI_TTY)) && [[ -z ${NO_COLOR:-} && ${TERM:-dumb} != dumb ]]; then UI_COLOR=1; fi
  if [[ ${GM_COLOR:-} == 1 ]]; then UI_COLOR=1; fi      # force on (tests)
  if [[ ${GM_COLOR:-} == 0 ]]; then UI_COLOR=0; fi      # force off (--no-color)

  # Box-drawing needs a UTF-8 locale: that is also what makes ${#var} count characters, not bytes.
  UI_UNICODE=0
  case ${LC_ALL:-${LC_CTYPE:-${LANG:-}}} in *[Uu][Tt][Ff]-8* | *[Uu][Tt][Ff]8*) UI_UNICODE=1 ;; esac
  if [[ ${GM_ASCII:-} == 1 ]]; then UI_UNICODE=0; fi
  if [[ ${TERM:-} == dumb ]]; then UI_UNICODE=0; fi

  ui_palette
  ui_glyphs
  ui_width
}

ui_palette() {
  C_0="" C_B="" C_DIM="" C_GRAY="" C_TITLE="" C_KEY="" C_OK="" C_ERR="" C_WARN="" C_INFO=""
  # readline-safe twins (escape sequences wrapped in \001 \002 so the cursor maths stay right)
  R_0="" R_TITLE="" R_DIM="" R_ERR="" R_OK="" R_WARN=""
  if ((UI_COLOR)); then
    C_0=$'\e[0m' C_B=$'\e[1m' C_DIM=$'\e[2m' C_GRAY=$'\e[90m'
    C_TITLE=$'\e[1;36m' C_KEY=$'\e[1;36m'
    C_OK=$'\e[1;32m' C_ERR=$'\e[1;31m' C_WARN=$'\e[1;33m' C_INFO=$'\e[1;34m'
    R_0=$'\001\e[0m\002' R_TITLE=$'\001\e[1;36m\002' R_DIM=$'\001\e[2m\002'
    R_ERR=$'\001\e[1;31m\002' R_OK=$'\001\e[1;32m\002' R_WARN=$'\001\e[1;33m\002'
  fi
}

ui_glyphs() {
  if ((UI_UNICODE)); then
    G_TL='╭' G_TR='╮' G_BL='╰' G_BR='╯' G_H='─' G_V='│' G_LT='├' G_RT='┤'
    G_DOT='·' G_SEP='›' G_PROMPT='❯' G_OK='✔' G_ERR='✖' G_WARN='▲' G_INFO='●' G_STEP='▸' G_ELL='…'
    UI_SPIN=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
  else
    G_TL='+' G_TR='+' G_BL='+' G_BR='+' G_H='-' G_V='|' G_LT='+' G_RT='+'
    G_DOT='.' G_SEP='>' G_PROMPT='>' G_OK='+' G_ERR='x' G_WARN='!' G_INFO='*' G_STEP='>' G_ELL='~'
    UI_SPIN=('|' '/' '-' '\')
  fi
}

# Outer width of every frame: the terminal width, clamped to 60..100 (re-read on each screen,
# so a resized window is picked up).
ui_width() {
  local c=${GM_COLUMNS:-}
  if [[ -z $c ]] && ((UI_TTY)); then c=$(tput cols 2>/dev/null || true); fi
  [[ $c =~ ^[0-9]+$ ]] || c=80
  ((c < 60)) && c=60
  ((c > 100)) && c=100
  UI_W=$c
}

# ---- string helpers (results go into the variable named by the first argument) ----------------
ui_vlen() {  # ui_vlen OUT "text"  -> visible length (colour escapes ignored)
  local -n __o_vlen=$1
  local __s=$2
  __s=${__s//$'\e'\[*([0-9;])m/}
  __o_vlen=${#__s}
}

ui_repeat() {  # ui_repeat OUT "char" N
  local -n __o_rep=$1
  local __n=$3 __t
  ((__n < 0)) && __n=0
  printf -v __t '%*s' "$__n" ''
  __o_rep=${__t// /$2}
}

ui_strip() {  # ui_strip OUT "text"  -> text without colour escapes
  local -n __o_strip=$1
  local __s=$2
  __o_strip=${__s//$'\e'\[*([0-9;])m/}
}

ui_clip() {  # ui_clip OUT "text" MAXWIDTH  -> text, or plain text cut with an ellipsis
  local -n __o_clip=$1
  local __s=$2 __max=$3 __len
  ui_vlen __len "$__s"
  if ((__len <= __max)); then
    __o_clip=$__s
  else
    ui_strip __s "$__s"
    ((__max < 2)) && __max=2
    __o_clip=${__s:0:__max-1}$G_ELL
  fi
}

ui_pad() {  # ui_pad OUT "text" WIDTH  -> text padded with spaces to WIDTH visible columns
  local -n __o_pad=$1
  local __s=$2 __w=$3 __len __sp
  ui_vlen __len "$__s"
  ui_repeat __sp ' ' $((__w - __len))
  __o_pad=$__s$__sp
}

# Untrusted text (hostnames from a log, inbound remarks, ...) must never reach the terminal raw:
# an embedded ESC sequence could rewrite the screen. ui_safe drops every control character.
ui_safe() {  # ui_safe OUT "text" [MAXLEN]
  local -n __o_safe=$1
  local __s=$2 __max=${3:-0}
  __s=${__s//[[:cntrl:]]/}
  if ((!UI_UNICODE)); then __s=${__s//[^ -~]/?}; fi      # byte-wise slicing in a non-UTF-8 locale would split characters
  if ((__max > 0 && ${#__s} > __max)); then __s=${__s:0:__max-1}$G_ELL; fi
  __o_safe=$__s
}

# ==== src/lib/20-render.sh ====
# shellcheck shell=bash
# 20-render.sh - frames, status cards, badges, messages, spinner.
#
# Nothing in here clears the screen: every screen is appended below the previous output, so the
# scrollback (what the last action printed) is never destroyed.

UI_KVW=12          # label column of key/value rows inside frames

# ---- badges ------------------------------------------------------------------------------------
# ui_badge OUT style [TEXT]   style: ok active warn fail info off   -> "[TEXT]" in the style colour
ui_badge() {
  local -n __o_badge=$1
  local style=$2 text=${3:-} col
  case $style in
    ok | active) col=$C_OK; : "${text:=OK}" ;;
    warn)        col=$C_WARN; : "${text:=WARN}" ;;
    fail | err)  col=$C_ERR; : "${text:=FAIL}" ;;
    info)        col=$C_INFO; : "${text:=INFO}" ;;
    *)           col=$C_GRAY; : "${text:=OFF}" ;;
  esac
  __o_badge="${col}[${text}]${C_0}"
}

# ---- frames ------------------------------------------------------------------------------------
ui_box_top() {  # ui_box_top ["Title"]
  local title=${1:-} inner=$((UI_W - 2)) fill len
  if [[ -n $title ]]; then
    ui_vlen len "$title"
    ui_repeat fill "$G_H" $((inner - len - 3))
    printf '%s%s%s%s %s%s%s %s%s%s\n' "$C_GRAY" "$G_TL" "$G_H" "$C_0" "$C_TITLE$title" "$C_0" "$C_GRAY" "$fill" "$G_TR" "$C_0"
  else
    ui_repeat fill "$G_H" "$inner"
    printf '%s%s%s%s%s\n' "$C_GRAY" "$G_TL" "$fill" "$G_TR" "$C_0"
  fi
}

ui_box_row() {  # ui_box_row "content"   (clipped / padded to the frame)
  local text=${1:-} w=$((UI_W - 4))
  ui_clip text "$text" "$w"
  ui_pad text "$text" "$w"
  printf '%s%s%s %s %s%s%s\n' "$C_GRAY" "$G_V" "$C_0" "$text" "$C_GRAY" "$G_V" "$C_0"
}

ui_box_sep() {
  local fill
  ui_repeat fill "$G_H" $((UI_W - 2))
  printf '%s%s%s%s%s\n' "$C_GRAY" "$G_LT" "$fill" "$G_RT" "$C_0"
}

ui_box_bottom() {
  local fill
  ui_repeat fill "$G_H" $((UI_W - 2))
  printf '%s%s%s%s%s\n' "$C_GRAY" "$G_BL" "$fill" "$G_BR" "$C_0"
}

ui_box_blank() { ui_box_row ""; }

# label (dim) + value on one row
ui_box_kv() {  # ui_box_kv "Label" "value"
  local label
  ui_pad label "$1" "$UI_KVW"
  ui_box_row "${C_DIM}${label}${C_0} ${2:-}"
}

# label + [BADGE] + detail, straight from the probe cache (see 50-probe.sh)
ui_box_probe() {  # ui_box_probe "Label" PROBE_ID
  local id=$2 badge detail
  if [[ -z ${PROBE_LVL[$id]:-} ]]; then
    ui_badge badge off "--"
    ui_box_kv "$1" "$badge ${C_DIM}not checked yet${C_0}"
    return 0
  fi
  ui_badge badge "${PROBE_LVL[$id]}" "${PROBE_BADGE[$id]}"
  detail=${PROBE_MSG[$id]}
  ui_box_kv "$1" "$badge ${detail}"
}

ui_banner() {  # ui_banner "Title" "subtitle"
  ui_box_top
  ui_box_row "${C_TITLE}${1:-$GM_APP}${C_0}"
  if [[ -n ${2:-} ]]; then ui_box_row "${C_DIM}$2${C_0}"; fi
  ui_box_bottom
}

# ---- single-line messages ----------------------------------------------------------------------
ui_say()  { printf '  %s\n' "$*"; }
ui_blank() { printf '\n'; }
ui_ok()   { printf '  %s%s%s %s\n' "$C_OK" "$G_OK" "$C_0" "$*"; }
ui_warn() { printf '  %s%s%s %s\n' "$C_WARN" "$G_WARN" "$C_0" "$*"; }
ui_err()  { printf '  %s%s%s %s\n' "$C_ERR" "$G_ERR" "$C_0" "$*"; }
ui_info() { printf '  %s%s%s %s\n' "$C_INFO" "$G_INFO" "$C_0" "$*"; }
ui_note() { printf '  %s%s%s\n' "$C_DIM" "$*" "$C_0"; }
ui_step() { printf '\n  %s%s %s%s\n' "$C_TITLE" "$G_STEP" "$*" "$C_0"; }

ui_rule() {  # ui_rule ["title"]   a light divider line between blocks of output
  local title=${1:-} fill len
  if [[ -n $title ]]; then
    ui_vlen len "$title"
    ui_repeat fill "$G_H" $((UI_W - 6 - len))
    printf '  %s%s%s %s%s%s %s%s%s\n' "$C_GRAY" "$G_H$G_H" "$C_0" "$C_TITLE" "$title" "$C_0" "$C_GRAY" "$fill" "$C_0"
  else
    ui_repeat fill "$G_H" $((UI_W - 2))
    printf '  %s%s%s\n' "$C_GRAY" "$fill" "$C_0"
  fi
}

# ---- spinner -----------------------------------------------------------------------------------
UI_TASK_PIDS=()
UI_TASK_OUT=""        # captured output of the last ui_task
UI_TASK_RC=0

ui_task_cleanup() {
  local p
  for p in "${UI_TASK_PIDS[@]:-}"; do
    [[ -n $p ]] && kill "$p" 2>/dev/null
  done
  UI_TASK_PIDS=()
  return 0
}

# ui_spin_wait "label" PID...   waits for background jobs with a spinner on a terminal.
# Environment: UI_WAIT_TIMEOUT=seconds (0 = none). Returns 0 done, 124 timed out (jobs killed),
# 130 interrupted by Ctrl-C (jobs killed). On 0 the caller does `wait PID` to get each exit status.
ui_spin_wait() {
  local label=$1 pid alive f=0 t0=$SECONDS rc=0 to=${UI_WAIT_TIMEOUT:-0}
  shift
  UI_TASK_PIDS=("$@")
  if ((UI_TTY)); then
    printf '  %s %s%s' "${UI_SPIN[0]}" "$label" "$C_DIM"
  else
    printf '  %s %s\n' "$G_ELL" "$label"
  fi
  while :; do
    alive=0
    for pid in "$@"; do
      if kill -0 "$pid" 2>/dev/null; then alive=1; break; fi
    done
    ((alive)) || break
    if ((GM_INT)); then rc=130; break; fi
    if ((to > 0 && SECONDS - t0 >= to)); then rc=124; break; fi
    if ((UI_TTY)); then
      f=$(((f + 1) % ${#UI_SPIN[@]}))
      printf '\r\e[K  %s%s%s %s%s' "$C_TITLE" "${UI_SPIN[f]}" "$C_0" "$label" "$C_DIM"
    fi
    sleep 0.1
  done
  if ((rc != 0)); then
    # killed jobs are reaped here; finished jobs are left for the caller's `wait PID` (exit status)
    for pid in "$@"; do kill "$pid" 2>/dev/null && wait "$pid" 2>/dev/null; done
  fi
  UI_TASK_PIDS=()
  if ((UI_TTY)); then printf '\r\e[K%s' "$C_0"; fi
  return "$rc"
}

# ui_task "label" cmd [args...]
# Runs cmd in the background (a subshell: it cannot change this shell's variables, return data on
# stdout), shows a spinner, then one result line. Output is captured in UI_TASK_OUT, status in
# UI_TASK_RC. On failure the last lines of output are shown. UI_TASK_QUIET=1 prints nothing on
# success.
ui_task() {
  local label=$1 out pid rc=0 t0=$SECONDS
  shift
  out=$(mktemp "${GM_TMP:-${TMPDIR:-/tmp}}/task.XXXXXX") || return 1
  (
    "$@"
  ) >"$out" 2>&1 &
  pid=$!
  ui_spin_wait "$label" "$pid" || rc=$?
  if ((rc == 0)); then
    wait "$pid" 2>/dev/null
    rc=$?
  fi
  UI_TASK_RC=$rc
  UI_TASK_OUT=$(<"$out")
  rm -f "$out"
  if ((rc == 0)); then
    if [[ ${UI_TASK_QUIET:-0} != 1 ]]; then ui_ok "$label ${C_DIM}($((SECONDS - t0))s)${C_0}"; fi
  else
    ui_err "$label ${C_DIM}(exit $rc)${C_0}"
    if [[ -n $UI_TASK_OUT ]]; then
      local line
      while IFS= read -r line; do ui_note "    ${line:0:$((UI_W - 8))}"; done < <(tail -n 5 <<<"$UI_TASK_OUT")
    fi
  fi
  return "$rc"
}

# ==== src/lib/30-input.sh ====
# shellcheck shell=bash
# 30-input.sh - buffered line input, validators and prompts that never kill the caller.
#
# Return-code contract shared by every prompt_* / confirm* function:
#     0  value accepted
#     1  (confirm only) the answer was "no"
#    10  cancelled: the user typed b / back / cancel, pressed Ctrl-D, or there is no terminal
# An invalid value never ends a prompt: it prints one inline error line and asks again.
# Inside an action a cancelled prompt is handled with:   prompt_ipv4 ip "Foreign IP" || act_cancel
#
# Input comes from the terminal even when the script itself is piped (curl ... | bash): when
# stdin is not a terminal, /dev/tty is opened on fd 9. GM_INPUT=stdin forces plain stdin (tests).

IN_FD=0 IN_OK=0 IN_TTY=0 IN_EOF=0 IN_VALUE="" IN_ERR="" IN_HINTED=0

in_init() {
  IN_OK=0 IN_TTY=0 IN_FD=0
  if [[ ${GM_INPUT:-} == stdin ]]; then
    IN_OK=1
  elif [[ -t 0 ]]; then
    IN_OK=1 IN_TTY=1
  elif [[ -r /dev/tty ]] && : 2>/dev/null </dev/tty; then
    exec 9</dev/tty
    IN_FD=9 IN_OK=1 IN_TTY=1
  fi
}

# "Label [default] ❯ " (colour escapes wrapped for readline)
in_prompt() {  # in_prompt OUT "label" ["default"]
  local -n __o_ip=$1
  local __p="  ${R_TITLE}$2${R_0}"
  if [[ -n ${3:-} ]]; then __p+=" ${R_DIM}[$3]${R_0}"; fi
  __o_ip="$__p ${R_TITLE}${G_PROMPT}${R_0} "
}

# One-time reminder per action / per menu, so the prompts themselves stay short.
in_hint_once() {
  if ((IN_HINTED == 0)); then
    ui_note "Enter accepts the [default]. Type b to cancel at any prompt. Ctrl-C stops the operation."
    IN_HINTED=1
  fi
}

# in_read OUT "prompt"   -> 0 got a line, 1 end of input, 130 Ctrl-C (only seen in the main shell:
# inside an action the INT trap ends the action first). Leading/trailing blanks are trimmed.
in_read() {
  local -n __o_ir=$1
  local __p=$2 __l="" __rc=0
  IN_EOF=0
  __o_ir=""
  if ((!IN_OK)); then IN_EOF=1; return 1; fi
  GM_INT=0
  if ((IN_TTY)); then
    GM_READING=1
    IFS= read -e -r -u "$IN_FD" -p "$__p" __l || __rc=$?
    GM_READING=0
  else
    __p=${__p//[$'\001\002']/}
    printf '%s' "$__p"
    IFS= read -r -u "$IN_FD" __l || __rc=$?
    if ((__rc == 1)) && [[ -n $__l ]]; then __rc=0; fi       # last line without a newline
  fi
  if ((__rc != 0)); then
    printf '\n'
    if ((__rc > 128 || GM_INT)); then return 130; fi
    IN_EOF=1
    return 1
  fi
  __l=${__l##+([[:space:]])}
  __l=${__l%%+([[:space:]])}
  __o_ir=$__l
  return 0
}

in_read_secret() {  # same contract as in_read, but nothing is echoed
  local -n __o_irs=$1
  local __p=$2 __l="" __rc=0
  IN_EOF=0
  __o_irs=""
  if ((!IN_OK)); then IN_EOF=1; return 1; fi
  GM_INT=0
  if ((IN_TTY)); then
    GM_READING=1
    IFS= read -rs -u "$IN_FD" -p "$__p" __l || __rc=$?
    GM_READING=0
  else
    __p=${__p//[$'\001\002']/}
    printf '%s' "$__p"
    IFS= read -r -u "$IN_FD" __l || __rc=$?
  fi
  printf '\n'
  if ((__rc != 0)); then
    if ((__rc > 128 || GM_INT)); then return 130; fi
    IN_EOF=1
    return 1
  fi
  __o_irs=$__l
  return 0
}

# ---- validators ------------------------------------------------------------------------------
# v_NAME value [args]  -> 0 valid. They set IN_VALUE (the normalised value) and, when invalid,
# IN_ERR (the message shown to the user). Pure functions: no output, no exit.
v_nonempty() {
  IN_VALUE=$1
  if [[ -n $1 ]]; then return 0; fi
  IN_ERR="a value is required"
  return 1
}

v_ipv4() {
  local v=$1 i o
  IN_ERR="not an IPv4 address (example: 203.0.113.10)"
  [[ $v =~ ^([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$ ]] || return 1
  for i in 1 2 3 4; do
    o=${BASH_REMATCH[i]}
    if ((${#o} > 1)) && [[ $o == 0* ]]; then return 1; fi
    ((10#$o <= 255)) || return 1
  done
  IN_VALUE=$v IN_ERR=""
}

v_int_range() {  # v_int_range value MIN MAX
  local v=$1 min=$2 max=$3
  IN_ERR="enter a whole number from $min to $max"
  [[ $v =~ ^[0-9]{1,9}$ ]] || return 1
  ((10#$v >= min && 10#$v <= max)) || return 1
  IN_VALUE=$((10#$v)) IN_ERR=""
}

v_port() { v_int_range "$1" 1 65535 || { IN_ERR="a port is a number from 1 to 65535"; return 1; }; }

v_hostname() {  # accepts "https://Host.Example/x", "full:host" ... and normalises to "host.example"
  local h=${1,,}
  h=${h#full:}
  h=${h#http://}
  h=${h#https://}
  h=${h%%/*}
  h=${h%%:*}
  h=${h%.}
  IN_ERR="not a valid hostname (example: gemini.google.com)"
  ((${#h} <= 253)) || return 1
  [[ $h =~ ^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$ ]] || return 1
  IN_VALUE=$h IN_ERR=""
}

v_yesno() {
  case ${1,,} in
    y | yes) IN_VALUE=y ;;
    n | no) IN_VALUE=n ;;
    *) IN_ERR="answer yes or no"; return 1 ;;
  esac
}

v_file_readable() {
  IN_ERR="no readable file at that path"
  [[ -f $1 && -r $1 ]] || return 1
  IN_VALUE=$1 IN_ERR=""
}

v_choice() {  # v_choice value OPTION...   (by number or by name, case-insensitive)
  local v=$1 i=0 o
  shift
  IN_ERR="pick one of the listed options (a number or its name)"
  if [[ $v =~ ^[0-9]+$ ]] && ((10#$v >= 1 && 10#$v <= $#)); then
    IN_VALUE=${!v} IN_ERR=""
    return 0
  fi
  for o in "$@"; do
    i=$((i + 1))
    if [[ ${o,,} == "${v,,}" ]]; then IN_VALUE=$o IN_ERR=""; return 0; fi
  done
  return 1
}

v_b64_bytes() {  # v_b64_bytes value N  -> base64 of exactly N bytes
  local v=${1//[$'\r\n\t ']/} n=$2
  IN_ERR="not base64 of exactly $n bytes"
  [[ $(printf '%s' "$v" | base64 -d 2>/dev/null | wc -c) == "$n" ]] || return 1
  IN_VALUE=$v IN_ERR=""
}

v_url() {
  IN_ERR="expected a URL starting with http:// or https://"
  [[ $1 =~ ^https?://[^[:space:]]+$ ]] || return 1
  IN_VALUE=$1 IN_ERR=""
}

v_tg_token() {
  IN_ERR="a Telegram bot token looks like 123456789:AAE... (digits, colon, letters)"
  [[ $1 =~ ^[0-9]{5,}:[A-Za-z0-9_-]{20,}$ ]] || return 1
  IN_VALUE=$1 IN_ERR=""
}

v_tg_chat() {
  IN_ERR="a chat id is a number like 123456789 or -1001234567890 (or @channelname)"
  [[ $1 =~ ^-?[0-9]{3,}$ || $1 =~ ^@[A-Za-z0-9_]{4,}$ ]] || return 1
  IN_VALUE=$1 IN_ERR=""
}

# ---- prompts ---------------------------------------------------------------------------------
# prompt_valid OUT "Label" "default" validator [validator-args...]
#   loops until the validator accepts; IN_ALLOW_EMPTY=1 lets an empty answer through as "".
prompt_valid() {
  local -n __o_pv=$1
  local __pv_label=$2 __pv_def=$3 __pv_fn=$4 __pv_line __pv_p __pv_rc
  shift 4
  in_hint_once
  while :; do
    in_prompt __pv_p "$__pv_label" "$__pv_def"
    in_read __pv_line "$__pv_p" && __pv_rc=0 || __pv_rc=$?
    if ((__pv_rc != 0)); then return 10; fi
    case ${__pv_line,,} in b | back | cancel) return 10 ;; esac
    if [[ -z $__pv_line ]]; then
      if [[ -n $__pv_def ]]; then
        __pv_line=$__pv_def
      elif [[ ${IN_ALLOW_EMPTY:-0} == 1 ]]; then
        __o_pv=""
        return 0
      else
        ui_err "a value is required (type b to cancel)"
        continue
      fi
    fi
    IN_VALUE=$__pv_line IN_ERR=""
    if "$__pv_fn" "$__pv_line" "$@"; then
      __o_pv=$IN_VALUE
      return 0
    fi
    ui_err "${IN_ERR:-invalid input}"
  done
}

prompt_text()     { prompt_valid "$1" "$2" "${3:-}" v_nonempty; }
prompt_ipv4()     { prompt_valid "$1" "$2" "${3:-}" v_ipv4; }
prompt_port()     { prompt_valid "$1" "$2" "${3:-}" v_port; }
prompt_hostname() { prompt_valid "$1" "$2" "${3:-}" v_hostname; }
prompt_int()      { prompt_valid "$1" "$2" "${5:-}" v_int_range "$3" "$4"; }   # OUT label MIN MAX [default]
prompt_file()     { prompt_valid "$1" "$2" "${3:-}" v_file_readable; }

prompt_choice() {  # prompt_choice OUT "Label" "default" option...
  local __pc_out=$1 __pc_label=$2 __pc_def=$3 __pc_i=0 __pc_o
  shift 3
  for __pc_o in "$@"; do
    __pc_i=$((__pc_i + 1))
    ui_say "  ${C_KEY}${__pc_i}${C_0}) $__pc_o"
  done
  prompt_valid "$__pc_out" "$__pc_label" "$__pc_def" v_choice "$@"
}

prompt_secret() {  # prompt_secret OUT "Label" [validator args...]   hidden input, empty/invalid is re-asked
  local -n __o_ps=$1
  local __ps_label=$2 __ps_fn=${3:-} __ps_l __ps_p __ps_rc
  shift 2
  shift || true
  in_hint_once
  while :; do
    in_prompt __ps_p "$__ps_label ${R_DIM}(hidden)${R_0}" ""
    in_read_secret __ps_l "$__ps_p" && __ps_rc=0 || __ps_rc=$?
    if ((__ps_rc != 0)); then return 10; fi
    case ${__ps_l,,} in b | back | cancel) return 10 ;; esac
    if [[ -z $__ps_l ]]; then
      ui_err "nothing was entered (type b to cancel)"
    elif [[ -z $__ps_fn ]]; then
      __o_ps=$__ps_l
      return 0
    else
      IN_VALUE=$__ps_l IN_ERR=""
      if "$__ps_fn" "$__ps_l" "$@"; then
        __o_ps=$IN_VALUE
        return 0
      fi
      ui_err "${IN_ERR:-invalid input}"
    fi
  done
}

# confirm "Question" [y|n]  -> 0 yes, 1 no, 10 cancelled.   --yes (GM_YES=1) answers yes.
confirm() {
  local __c_q=$1 __c_def=${2:-} __c_hint __c_l __c_p __c_rc
  if [[ $GM_YES == 1 ]]; then
    ui_note "auto-confirmed (--yes): $__c_q"
    return 0
  fi
  case $__c_def in y) __c_hint="Y/n" ;; n) __c_hint="y/N" ;; *) __c_hint="y/n" ;; esac
  while :; do
    in_prompt __c_p "$__c_q ${R_DIM}[$__c_hint]${R_0}" ""
    in_read __c_l "$__c_p" && __c_rc=0 || __c_rc=$?
    if ((__c_rc != 0)); then return 10; fi
    case ${__c_l,,} in
      y | yes) return 0 ;;
      n | no) return 1 ;;
      b | back | cancel) return 10 ;;
      "")
        if [[ $__c_def == y ]]; then return 0; fi
        if [[ $__c_def == n ]]; then return 1; fi
        ui_err "please answer yes or no"
        ;;
      *) ui_err "please answer y or n (b to cancel)" ;;
    esac
  done
}

_confirm_typed() {  # _confirm_typed honour_yes "message" word
  local __t_msg=$2 __t_word=${3:-yes} __t_l __t_p __t_rc
  if [[ $1 == 1 && $GM_YES == 1 ]]; then return 0; fi
  ui_warn "$__t_msg"
  while :; do
    in_prompt __t_p "Type ${R_WARN}${__t_word}${R_0}${R_TITLE} to continue, b to cancel" ""
    in_read __t_l "$__t_p" && __t_rc=0 || __t_rc=$?
    if ((__t_rc != 0)); then return 10; fi
    case ${__t_l,,} in
      "$__t_word") return 0 ;;
      b | back | cancel) return 10 ;;
      "") ;;
      *) ui_err "not confirmed - type exactly '$__t_word', or b to cancel" ;;
    esac
  done
}
confirm_typed()       { _confirm_typed 1 "$@"; }     # --yes skips it
confirm_typed_force() { _confirm_typed 0 "$@"; }     # --yes can NOT skip it (secrets, destructive)

# pick_many RESULT "Title" LABELS SELECTED
#   RESULT, LABELS and SELECTED are array names. SELECTED holds the initial 0/1 flags.
#   Returns 0 with RESULT = 0-based indexes of the ticked rows, or 10 when cancelled (the caller's
#   arrays are then left exactly as they were). Input is parsed without globbing and validated as
#   a whole: one bad token rejects the line and nothing is toggled.
pick_many() {
  local -n __pm_res=$1 __pm_labels=$3 __pm_init=$4
  local __pm_title=$2 __pm_n=${#__pm_labels[@]} __pm_i __pm_l __pm_p __pm_rc __pm_tok __pm_bad __pm_done
  local -a __pm_sel=() __pm_toks=()
  local __pm_a __pm_b __pm_t __pm_show
  for ((__pm_i = 0; __pm_i < __pm_n; __pm_i++)); do __pm_sel[__pm_i]=${__pm_init[__pm_i]:-0}; done
  in_hint_once
  while :; do
    ui_rule "$__pm_title"
    for ((__pm_i = 0; __pm_i < __pm_n; __pm_i++)); do
      ui_safe __pm_show "${__pm_labels[__pm_i]}" $((UI_W - 16))
      if ((__pm_sel[__pm_i] == 1)); then
        ui_say "${C_OK}[x]${C_0} ${C_KEY}$((__pm_i + 1))${C_0}  $__pm_show"
      else
        ui_say "${C_DIM}[ ]${C_0} ${C_KEY}$((__pm_i + 1))${C_0}  $__pm_show"
      fi
    done
    ui_note "numbers toggle (1 3 5-7)  a = all  n = none  d = done  b = cancel"
    while :; do
      in_prompt __pm_p "Toggle" ""
      in_read __pm_l "$__pm_p" && __pm_rc=0 || __pm_rc=$?
      if ((__pm_rc != 0)); then return 10; fi
      read -ra __pm_toks <<<"$__pm_l"                      # word-split without globbing
      if ((${#__pm_toks[@]} == 0)); then continue; fi
      __pm_bad=""
      for __pm_tok in "${__pm_toks[@]}"; do
        __pm_t=${__pm_tok,,}
        if [[ $__pm_t =~ ^[andb]$ ]]; then
          :
        elif [[ $__pm_t =~ ^[0-9]+$ ]]; then
          if ((10#$__pm_t < 1 || 10#$__pm_t > __pm_n)); then __pm_bad=$__pm_tok; fi
        elif [[ $__pm_t =~ ^([0-9]+)-([0-9]+)$ ]]; then
          __pm_a=${BASH_REMATCH[1]} __pm_b=${BASH_REMATCH[2]}
          if ((10#$__pm_a < 1 || 10#$__pm_b > __pm_n || 10#$__pm_a > 10#$__pm_b)); then __pm_bad=$__pm_tok; fi
        else
          __pm_bad=$__pm_tok
        fi
        if [[ -n $__pm_bad ]]; then break; fi
      done
      if [[ -n $__pm_bad ]]; then
        ui_safe __pm_bad "$__pm_bad" 20
        ui_err "\"$__pm_bad\" is not valid here - use numbers 1-$__pm_n (or 2-4), a, n, d or b. Nothing was changed."
        continue
      fi
      __pm_done=0
      for __pm_tok in "${__pm_toks[@]}"; do
        __pm_t=${__pm_tok,,}
        if [[ $__pm_t == a ]]; then
          for ((__pm_i = 0; __pm_i < __pm_n; __pm_i++)); do __pm_sel[__pm_i]=1; done
        elif [[ $__pm_t == n ]]; then
          for ((__pm_i = 0; __pm_i < __pm_n; __pm_i++)); do __pm_sel[__pm_i]=0; done
        elif [[ $__pm_t == d ]]; then
          __pm_done=1
          break
        elif [[ $__pm_t == b ]]; then
          return 10
        elif [[ $__pm_t =~ ^[0-9]+$ ]]; then
          __pm_i=$((10#$__pm_t - 1))
          __pm_sel[__pm_i]=$((1 - __pm_sel[__pm_i]))
        elif [[ $__pm_t =~ ^([0-9]+)-([0-9]+)$ ]]; then
          __pm_a=${BASH_REMATCH[1]} __pm_b=${BASH_REMATCH[2]}
          for ((__pm_i = 10#$__pm_a - 1; __pm_i < 10#$__pm_b; __pm_i++)); do __pm_sel[__pm_i]=$((1 - __pm_sel[__pm_i])); done
        fi
      done
      if ((__pm_done)); then
        __pm_res=()
        for ((__pm_i = 0; __pm_i < __pm_n; __pm_i++)); do
          if ((__pm_sel[__pm_i] == 1)); then __pm_res+=("$__pm_i"); fi
        done
        return 0
      fi
      break      # redraw the list with the new ticks
    done
  done
}

# ==== src/lib/40-action.sh ====
# shellcheck shell=bash
# 40-action.sh - the action runner: one place that gives every operation the same guarantees.
#
#   act_run "Label" function [args...]        run function as an action, print ONE result line
#
# Guarantees
#   * errexit + ERR trap are really on inside the action. (The old design broke this: bash silently
#     disables `set -e` for everything called from `cmd || true` / `if cmd` / `cmd && ...`.
#     act_run therefore REFUSES to run from such a context - it returns 70 and says so - instead
#     of pretending.)  Call it as its own statement and read $ACT_RC or $?:
#           act_run "Restart relay" iran_restart; rc=$?
#   * Ctrl-C ends only the action: its rollbacks and deferred cleanups run, the result line says
#     INTERRUPTED and the caller (the menu) carries on.
#   * exit codes:  0 ok | 10 cancelled | 130 interrupted | 70 runner misuse | other = failed
#   * the action runs in a subshell: it cannot change the caller's variables. Persist state on
#     disk or print it; read it afterwards from there.
#
# Helpers for use INSIDE an action (they all end the action, even when errexit is suppressed):
#   act_step "title"            numbered progress heading
#   must cmd args...            run a command; on failure print it and end the action with its code
#   act_do "what" cmd args...   like must, but in dry-run only says what it would do
#   act_fail "message" [rc]     print an error and end the action (default rc 1)
#   act_cancel ["message"]      end the action as "cancelled, nothing changed" (rc 10)
#   act_defer cmd args...       cleanup that always runs when the action ends (LIFO)
#   act_on_fail cmd args...     rollback that runs only when the action ends non-zero (LIFO)
#   act_commit                  forget the rollbacks registered so far (the step is durable now)
#   act_partial "what stays"    record that the failure left something applied (shown as PARTIAL)
#   act_tip "what to do next"   one-line advice shown under the PARTIAL list (e.g. how to undo)

ACT_IN=0 ACT_RC=0 ACT_LABEL="" ACT_STATE="" ACT_N=0 ACT_SUPPRESSED=0
ACT_DEFERS=() ACT_ROLLBACKS=()

# Is errexit being ignored in the calling context? (plain statement call only: inside `if f` the
# probe would always answer "yes")
act_probe_ctx() {
  local r
  r=$(
    set -e
    false
    echo x
  )
  if [[ $r == x ]]; then ACT_SUPPRESSED=1; else ACT_SUPPRESSED=0; fi
  return 0
}

act_run() {
  local __label=$1 __rc __t0=$SECONDS
  shift
  ACT_LABEL=$__label
  act_probe_ctx
  if ((ACT_SUPPRESSED)); then
    ui_err "internal error: act_run was called from a context where errexit is disabled (|| && if)."
    ui_note "Call it as its own statement:   act_run \"Label\" fn; rc=\$?"
    ACT_RC=70
    return 70
  fi
  gm_tmp_init
  ACT_STATE=$GM_TMP/act.state
  : >"$ACT_STATE"
  GM_INT=0
  trap gm_on_int INT           # the main shell survives Ctrl-C; the subshell below handles it
  (act_child "$@")
  __rc=$?
  GM_INT=0
  ACT_RC=$__rc
  act_report "$__rc" "$__label" $((SECONDS - __t0))
  if declare -F gm_audit >/dev/null; then gm_audit "action '$__label' rc=$__rc dry=$GM_DRY"; fi
  return "$__rc"
}

# ---- inside the subshell -----------------------------------------------------------------------
act_child() {
  ACT_IN=1 ACT_N=0 ACT_DEFERS=() ACT_ROLLBACKS=() IN_HINTED=0
  set -eE
  trap 'act_on_err $? "${BASH_COMMAND:-?}"' ERR
  trap 'act_on_int' INT
  trap 'act_on_exit $?' EXIT
  "$@"
}

act_on_err() {  # act_on_err RC "command"
  trap - ERR
  if (($1 == 10)); then exit 10; fi      # a cancelled prompt: not an error, no noise
  ui_err "step failed (exit $1): $2"
  exit "$1"
}

act_on_int() {
  trap - INT ERR
  printf '\n'
  ui_warn "Interrupted (Ctrl-C) - stopping this operation"
  exit 130
}

act_on_exit() {
  local rc=$1 i
  trap - EXIT INT ERR
  set +e
  if ((rc != 0 && ${#ACT_ROLLBACKS[@]} > 0)); then
    ui_warn "rolling back the steps of this operation that were not completed"
    for ((i = ${#ACT_ROLLBACKS[@]} - 1; i >= 0; i--)); do eval "${ACT_ROLLBACKS[i]}" || true; done
  fi
  for ((i = ${#ACT_DEFERS[@]} - 1; i >= 0; i--)); do eval "${ACT_DEFERS[i]}" || true; done
  ui_task_cleanup
}

act_step()     { ACT_N=$((ACT_N + 1)); ui_step "[$ACT_N] $*"; }
act_defer()    { ACT_DEFERS+=("$(printf '%q ' "$@")"); }
act_on_fail()  { ACT_ROLLBACKS+=("$(printf '%q ' "$@")"); }
act_commit()   { ACT_ROLLBACKS=(); }
act_partial()  { printf '%s\n' "$*" >>"${ACT_STATE:-/dev/null}"; }
act_tip()      { printf 'tip: %s\n' "$*" >>"${ACT_STATE:-/dev/null}"; }

act_cancel() {
  if [[ -n ${1:-} ]]; then ui_note "$1"; fi
  if ((ACT_IN)); then exit 10; fi
  return 10
}

act_fail() {
  ui_err "${1:-failed}"
  if ((ACT_IN)); then exit "${2:-1}"; fi
  return "${2:-1}"
}

must() {
  local __rc=0
  "$@" || __rc=$?
  if ((__rc == 0)); then return 0; fi
  ui_err "command failed (exit $__rc): $*"
  if ((ACT_IN)); then exit "$__rc"; fi
  return "$__rc"
}

act_do() {  # act_do "description" cmd args...
  local __what=$1
  shift
  if is_dry; then
    ui_info "${C_WARN}dry-run${C_0}: would $__what"
    return 0
  fi
  ui_note "$__what"
  must "$@"
}

# ---- result line -------------------------------------------------------------------------------
act_report() {  # act_report RC "label" SECONDS
  local rc=$1 label=$2 secs=$3 badge line meta=""
  if ((secs > 0)); then meta=" ${C_DIM}(${secs}s)${C_0}"; fi
  ui_blank
  if ((rc == 0)); then
    if is_dry; then
      ui_badge badge warn "DRY-RUN"
      ui_say "$badge  $label ${C_DIM}- nothing was changed${C_0}"
    elif [[ ${ACT_QUIET_OK:-0} != 1 ]]; then
      ui_badge badge ok " OK "
      ui_say "$badge  $label$meta"
    fi
  elif ((rc == 10)); then
    ui_badge badge warn "CANCELLED"
    ui_say "$badge  $label ${C_DIM}- nothing was changed${C_0}"
  elif ((rc == 130)); then
    ui_badge badge warn "INTERRUPTED"
    ui_say "$badge  $label ${C_DIM}- stopped by Ctrl-C${C_0}"
  elif ((rc == 70)); then
    ui_badge badge fail "ERROR"
    ui_say "$badge  $label ${C_DIM}- runner misuse, see above${C_0}"
  else
    ui_badge badge fail "FAILED"
    ui_say "$badge  $label ${C_DIM}(exit $rc)${C_0}"
  fi
  if ((rc != 0 && rc != 10)) && [[ -s $ACT_STATE ]]; then
    local -a tips=()
    ui_badge badge warn "PARTIAL"
    ui_say "$badge  these parts were applied and KEPT:"
    while IFS= read -r line; do
      if [[ $line == tip:* ]]; then tips+=("${line#tip: }"); else ui_say "       - $line"; fi
    done <"$ACT_STATE"
    for line in "${tips[@]}"; do ui_note "       $G_SEP $line"; done
  elif ((rc != 0)); then
    ui_note "  (details are in the messages above)"
  fi
  return 0
}

# ==== src/lib/50-probe.sh ====
# shellcheck shell=bash
# 50-probe.sh - status probes: cached, run in parallel, with a spinner and a timeout.
#
# A probe is a function that prints ONE line, tab-separated:
#       LEVEL <TAB> BADGE <TAB> detail text [<TAB> what to do about it]
#   LEVEL is ok | warn | fail | info | off (it picks the colour), BADGE is the short word shown
#   in the brackets ("ACTIVE", "FAIL", "OFF", ...).
# Probes run in subshells, all at once, so a slow one (DNS) costs the time of the slowest, not
# the sum - and the screen shows a spinner instead of freezing. A probe that does not answer within
# GM_PROBE_TIMEOUT seconds (default 12) is shown as a warning and never blocks the menu.
#
#   probe_register ID function "Label"     once, at start-up
#   probe_refresh [force]                  re-run them unless the cache is younger than the TTL
#   probe_invalidate                       mark stale (the menu does this after every action)
#   ui_box_probe "Label" ID                draw one row of a status card from the cache

declare -A PROBE_FN=() PROBE_LABEL=() PROBE_LVL=() PROBE_BADGE=() PROBE_MSG=() PROBE_HINT=()
PROBE_IDS=()
PROBE_AT=-1                        # SECONDS value of the last refresh; -1 = stale
PROBE_TTL=${GM_STATUS_TTL:-30}

probe_register() {  # probe_register ID function "Label"
  [[ $1 =~ ^[a-z0-9_]+$ ]] || gm_fatal "probe id must be [a-z0-9_]+: $1"
  PROBE_IDS+=("$1")
  PROBE_FN[$1]=$2
  PROBE_LABEL[$1]=${3:-$1}
}

probe_invalidate() { PROBE_AT=-1; }

probe_refresh() {  # probe_refresh [force]
  local force=${1:-0} id pid rc=0 n=${#PROBE_IDS[@]} lvl badge msg hint line f
  local -a pids=()
  if ((n == 0)); then return 0; fi
  if ((!force && PROBE_AT >= 0 && SECONDS - PROBE_AT < PROBE_TTL)); then return 0; fi
  gm_tmp_init
  for id in "${PROBE_IDS[@]}"; do
    f=$GM_TMP/probe.$id
    : >"$f"
    ("${PROBE_FN[$id]}") >"$f" 2>/dev/null &
    pids+=("$!")
  done
  UI_WAIT_TIMEOUT=${GM_PROBE_TIMEOUT:-12} ui_spin_wait "Checking status ($n checks)..." "${pids[@]}" || rc=$?
  if ((rc == 130)); then
    ui_warn "status refresh interrupted - showing the previous values"
    return 130
  fi
  for id in "${PROBE_IDS[@]}"; do
    f=$GM_TMP/probe.$id
    line=""
    if [[ -s $f ]]; then IFS= read -r line <"$f" || true; fi
    lvl="" badge="" msg="" hint=""
    IFS=$'\t' read -r lvl badge msg hint <<<"$line" || true
    case $lvl in
      ok | warn | fail | info | off) ;;
      *)
        lvl=warn badge="?"
        if ((rc == 124)); then msg="did not answer in time (skipped)"; else msg="the check returned no usable result"; fi
        hint="Press r to try again."
        ;;
    esac
    ui_safe badge "$badge" 10
    ui_safe msg "$msg" $((UI_W - UI_KVW - 18))
    ui_safe hint "$hint" $((UI_W - 10))
    PROBE_LVL[$id]=$lvl PROBE_BADGE[$id]=$badge PROBE_MSG[$id]=$msg PROBE_HINT[$id]=$hint
  done
  for pid in "${pids[@]}"; do wait "$pid" 2>/dev/null || true; done
  PROBE_AT=$SECONDS
  return 0
}

# worst level in the cache: prints ok | warn | fail
probe_worst() {
  local id w=ok
  for id in "${PROBE_IDS[@]}"; do
    case ${PROBE_LVL[$id]:-} in
      fail) echo fail; return 0 ;;
      warn) w=warn ;;
    esac
  done
  echo "$w"
}

# Full report with "what to do" lines (the Health check screen).
probe_report() {
  local id badge
  if ((${#PROBE_IDS[@]} == 0)); then ui_note "no checks are registered"; return 0; fi
  for id in "${PROBE_IDS[@]}"; do
    ui_badge badge "${PROBE_LVL[$id]:-off}" "${PROBE_BADGE[$id]:-?}"
    ui_say "$badge ${C_B}${PROBE_LABEL[$id]}${C_0}  ${PROBE_MSG[$id]:-not checked yet}"
    if [[ ${PROBE_LVL[$id]:-} =~ ^(warn|fail)$ && -n ${PROBE_HINT[$id]:-} ]]; then
      ui_note "      $G_SEP ${PROBE_HINT[$id]}"
    fi
  done
}

# ==== src/lib/60-menu.sh ====
# shellcheck shell=bash
# 60-menu.sh - data-driven menu engine. Screens are DATA, not hand-written loops.
#
#   menu_screen NAME "Title" [status_fn] [build_fn]
#   menu_item   NAME KEY "Label" "hint" HANDLER [enable_fn]
#   menu_run    ROOT_SCREEN                      (call it as its own statement, not after || / if)
#
# HANDLER kinds
#   screen:NAME     push another screen (b goes back)
#   action:fn args  run fn through act_run: errexit, Ctrl-C handling, one RESULT line
#   view:fn args    like action, but prints nothing on success (read-only displays)
#   call:fn args    run fn in this shell, no isolation (for menu-state tweaks only)
#   back | quit
#
# status_fn  draws the status card above the menu (use ui_box_* and probe_refresh).
# build_fn   runs before every render; it may call menu_reset NAME + menu_item to (re)build
#            dynamic items (a domain list, a backup list).
# enable_fn  returns non-zero to grey an item out; it can set MENU_WHY to say why.
#
# Standard keys, always available on every screen (so items may not use them):
#   b back   q quit   r refresh status   d toggle dry-run   ? help
# Input is a line: type the key, edit with backspace/arrows, press Enter. Nothing fires on a
# single keypress. Unknown input prints one inline error; the screen is NOT redrawn.

declare -A M_TITLE=() M_ITEMS=() M_STATUS=() M_BUILD=()
MENU_STACK=()
MENU_QUIT=0 MENU_REDRAW=0 MENU_WHY=""
MENU_US=$'\x1f'
MENU_RESERVED=" b q r d h ? back quit exit refresh help "

menu_screen() {  # menu_screen NAME "Title" [status_fn] [build_fn]
  [[ $1 =~ ^[a-z0-9_]+$ ]] || gm_fatal "screen name must be [a-z0-9_]+: $1"
  M_TITLE[$1]=$2
  M_STATUS[$1]=${3:-}
  M_BUILD[$1]=${4:-}
  M_ITEMS[$1]=""
}

menu_reset() { M_ITEMS[$1]=""; }

menu_item() {  # menu_item NAME KEY "Label" "hint" HANDLER [enable_fn]
  local name=$1 key=${2,,} label=$3 hint=${4:-} handler=$5 enable=${6:-}
  [[ -n ${M_TITLE[$name]:-} ]] || gm_fatal "menu_item: screen '$name' is not defined"
  [[ $key =~ ^[a-z0-9]{1,3}$ ]] || gm_fatal "menu key must be 1-3 letters/digits: '$2'"
  [[ $MENU_RESERVED != *" $key "* ]] || gm_fatal "menu key '$key' is reserved (screen $name)"
  [[ $handler =~ ^(screen:[a-z0-9_]+|action:.+|view:.+|call:.+|back|quit)$ ]] \
    || gm_fatal "menu item '$key' on '$name': bad handler '$handler'"
  if [[ ${M_ITEMS[$name]} == "$key$MENU_US"* || ${M_ITEMS[$name]} == *$'\n'"$key$MENU_US"* ]]; then
    gm_fatal "menu key '$key' is used twice on screen '$name'"
  fi
  M_ITEMS[$name]+="$key$MENU_US$label$MENU_US$hint$MENU_US$handler$MENU_US$enable"$'\n'
}

menu_crumbs() {  # menu_crumbs OUT  -> "Main > Domains"
  local -n __o_cr=$1
  local s out=""
  for s in "${MENU_STACK[@]}"; do
    if [[ -n $out ]]; then out+=" $G_SEP "; fi
    out+=${M_TITLE[$s]}
  done
  __o_cr=$out
}

menu_render() {  # menu_render NAME
  local name=$1 crumbs key label hint handler enable why i n=0 kw=0 lw=0 rem kc lc hc foot dm
  local -a K=() L=() H=() W=() X=()
  ui_width
  if [[ -n ${M_BUILD[$name]:-} ]]; then "${M_BUILD[$name]}"; fi
  ui_blank
  if [[ -n ${M_STATUS[$name]:-} ]]; then
    "${M_STATUS[$name]}"
    ui_blank
  fi
  while IFS=$MENU_US read -r key label hint handler enable; do
    [[ -n $key ]] || continue
    why=""
    MENU_WHY=""
    if [[ -n $enable ]] && ! "$enable"; then why=${MENU_WHY:-unavailable}; fi
    K+=("$key") L+=("$label") H+=("$hint") W+=("$why")
    if ((${#key} + 2 > kw)); then kw=$((${#key} + 2)); fi
    if ((${#label} > lw)); then lw=${#label}; fi
    n=$((n + 1))
  done <<<"${M_ITEMS[$name]}"
  ((lw > 34)) && lw=34

  menu_crumbs crumbs
  ui_box_top "$crumbs"
  if is_dry; then ui_box_row "${C_WARN}DRY-RUN is ON: actions only describe what they would do${C_0}"; fi
  if ((n == 0)); then ui_box_row "${C_DIM}(nothing here yet)${C_0}"; fi
  for ((i = 0; i < n; i++)); do
    if [[ -n ${W[i]} ]]; then
      kc="${C_DIM}[${K[i]}]${C_0}"
      ui_clip lc "${L[i]}" "$lw"
      hc="(${W[i]})"
      ui_pad kc "$kc" "$kw"
      ui_pad lc "${C_DIM}${lc}${C_0}" "$lw"
      ui_box_row " $kc  $lc  ${C_DIM}${hc}${C_0}"
    else
      kc="${C_KEY}[${K[i]}]${C_0}"
      ui_clip lc "${L[i]}" "$lw"
      ui_pad kc "$kc" "$kw"
      ui_pad lc "$lc" "$lw"
      rem=$((UI_W - 4 - 1 - kw - 2 - lw - 2))
      hc=""
      if ((rem > 3 && ${#H[i]} > 0)); then
        ui_clip hc "${H[i]}" "$rem"
        hc="${C_DIM}${hc}${C_0}"
      fi
      ui_box_row " $kc  $lc  $hc"
    fi
  done
  ui_box_sep
  if is_dry; then dm="ON"; else dm="off"; fi
  foot=""
  if ((${#MENU_STACK[@]} > 1)); then foot+="${C_KEY}[b]${C_0} Back  "; fi
  foot+="${C_KEY}[q]${C_0} Quit  ${C_KEY}[r]${C_0} Refresh  ${C_KEY}[d]${C_0} Dry-run ${dm}  ${C_KEY}[?]${C_0} Help"
  ui_box_row " $foot"
  ui_box_bottom
}

menu_help() {
  ui_blank
  ui_rule "How this menu works"
  ui_say "Type the key of an item (for example ${C_KEY}1${C_0}) and press ${C_B}Enter${C_0}."
  ui_say "Nothing runs until you press Enter, so you can correct a typo with Backspace."
  ui_say "${C_KEY}b${C_0} back   ${C_KEY}q${C_0} quit   ${C_KEY}r${C_0} refresh the status   ${C_KEY}d${C_0} toggle dry-run"
  ui_say "Ctrl-C stops the operation that is running; it never closes the menu."
  ui_say "Inside an operation, type ${C_KEY}b${C_0} at any prompt to cancel it."
  ui_blank
}

menu_pop() {
  if ((${#MENU_STACK[@]} > 1)); then
    unset 'MENU_STACK[-1]'
    MENU_REDRAW=1
  else
    ui_note "You are at the top level. Type q to quit."
  fi
}

menu_invoke() {  # menu_invoke "label" handler
  local label=$1 handler=$2 kind arg
  local -a argv=()
  kind=${handler%%:*}
  arg=${handler#*:}
  case $kind in
    screen)
      if [[ -z ${M_TITLE[$arg]:-} ]]; then ui_err "screen '$arg' is not defined"; return 0; fi
      MENU_STACK+=("$arg")
      MENU_REDRAW=1
      ;;
    action)
      read -r -a argv <<<"$arg"
      act_run "$label" "${argv[@]}"
      if ((ACT_RC != 10)); then probe_invalidate; fi      # a cancelled action changed nothing
      MENU_REDRAW=1
      ;;
    view)
      read -r -a argv <<<"$arg"
      ACT_QUIET_OK=1 act_run "$label" "${argv[@]}"
      MENU_REDRAW=1
      ;;
    call)
      read -r -a argv <<<"$arg"
      "${argv[@]}" || ui_err "'${argv[0]}' returned an error"
      MENU_REDRAW=1
      ;;
    back) menu_pop ;;
    quit) MENU_QUIT=1 ;;
  esac
}

menu_dispatch() {  # menu_dispatch SCREEN "typed text"
  local name=$1 typed=$2 in key label hint handler enable why shown found=0
  in=${typed,,}
  MENU_REDRAW=0
  case $in in
    "") return 0 ;;
    q | quit | exit) MENU_QUIT=1; return 0 ;;
    b | back) menu_pop; return 0 ;;
    r | refresh) probe_invalidate; MENU_REDRAW=1; return 0 ;;
    d)
      if is_dry; then GM_DRY=0; ui_ok "Dry-run is OFF: actions will change things"; else GM_DRY=1; ui_warn "Dry-run is ON: actions will only describe what they would do"; fi
      MENU_REDRAW=1
      return 0
      ;;
    "?" | h | help) menu_help; return 0 ;;
  esac
  # Find the item first, run it AFTER the loop: inside `while read <<<...` stdin is the item list,
  # and an action that prompts would read its answers from there instead of the keyboard.
  while IFS=$MENU_US read -r key label hint handler enable; do
    if [[ $key == "$in" ]]; then found=1; break; fi
  done <<<"${M_ITEMS[$name]}"
  if ((!found)); then
    ui_safe shown "$typed" 24
    ui_err "\"$shown\" is not an option here - type a key from the list (for example ${C_KEY}1${C_0}), or ? for help"
    return 0
  fi
  why=""
  MENU_WHY=""
  if [[ -n $enable ]] && ! "$enable"; then why=${MENU_WHY:-unavailable}; fi
  if [[ -n $why ]]; then
    ui_warn "\"$label\" is not available right now: $why"
    return 0
  fi
  menu_invoke "$label" "$handler"
  return 0
}

menu_run() {  # menu_run ROOT
  local cur line rc crumbs prompt redraw=1
  if [[ -z ${M_TITLE[$1]:-} ]]; then gm_fatal "menu_run: screen '$1' is not defined"; fi
  MENU_STACK=("$1")
  MENU_QUIT=0
  if ((!IN_OK)); then
    ui_err "the menu needs a terminal for input"
    return 1
  fi
  while ((!MENU_QUIT && ${#MENU_STACK[@]} > 0)); do
    cur=${MENU_STACK[-1]}
    if ((redraw)); then
      menu_render "$cur"
      redraw=0
    fi
    menu_crumbs crumbs
    in_prompt prompt "$crumbs" ""
    in_read line "$prompt" && rc=0 || rc=$?
    case $rc in
      0) ;;
      130)
        ui_note "Ctrl-C only cancels a running operation. Type q to quit, b to go back."
        continue
        ;;
      *)
        MENU_QUIT=1
        continue
        ;;
    esac
    menu_dispatch "$cur" "$line"
    redraw=$MENU_REDRAW
  done
  return 0
}

# ==== src/entry/demo.sh ====
# demo.sh - a small fake "relay manager" that exercises every part of the Phase 1 foundation.
# It doubles as the reference for how Phase 2 plugs the real Iran / foreign logic in:
#
#   1. register probes      probe_register id fn "Label"      (fast, parallel, cached status)
#   2. write a status card  ui_box_* + ui_box_probe           (the dashboard header)
#   3. write actions        plain functions; prompts + act_* helpers; state goes to disk
#   4. declare screens      menu_screen / menu_item           (data, not loops)
#   5. menu_run main
#
# Nothing here touches the machine: the "service" is a file in a temp directory.

set -uo pipefail
umask 077

DEMO_DIR=""

# ---------------------------------------------------------------- fake backend ------------------
demo_seed() {
  DEMO_DIR=$GM_TMP/demo
  mkdir -p "$DEMO_DIR"
  echo running >"$DEMO_DIR/service"
  printf '%s\n' gemini.google.com aistudio.google.com generativelanguage.googleapis.com \
    proactivebackend-pa.googleapis.com >"$DEMO_DIR/domains"
}

demo_domains_without() {  # rewrite the list without $1 (grep -v exits 1 on an empty result)
  { grep -vxF -- "$1" "$DEMO_DIR/domains" || true; } >"$DEMO_DIR/domains.new"
  mv -f "$DEMO_DIR/domains.new" "$DEMO_DIR/domains"
}

# ---------------------------------------------------------------- probes -----------------------
# Each prints: LEVEL <TAB> BADGE <TAB> detail [<TAB> hint]
probe_relay() {
  if [[ $(<"$DEMO_DIR/service") == running ]]; then
    printf 'ok\tACTIVE\txray-gemini %s listening on :20443\n' "$G_DOT"
  else
    printf 'fail\tSTOPPED\txray-gemini is not running\tService > Start\n'
  fi
}
probe_routing() { printf 'ok\tON\t%s hosts routed to Iran\n' "$(wc -l <"$DEMO_DIR/domains")"; }
probe_dns() {
  sleep "${DEMO_DNS_DELAY:-1.5}"          # a slow live check: costs one spinner, not a frozen screen
  printf 'ok\tOK\tShecan answers differ from a neutral resolver\n'
}
probe_fw() { printf 'warn\tNO RULE\tnothing allows 198.51.100.7 to reach :20443\tService > Repair firewall\n'; }

# ---------------------------------------------------------------- status cards ------------------
demo_status() {
  probe_refresh
  ui_box_top "GEMINI $G_DOT SHECAN"
  ui_box_kv "Role" "${C_B}IRAN relay${C_0} ${C_DIM}(demo)${C_0}"
  ui_box_probe "Relay" relay
  ui_box_probe "Routing" routing
  ui_box_probe "Shecan DNS" dns
  ui_box_probe "Firewall" fw
  ui_box_kv "Addresses" "203.0.113.10 ${C_DIM}$G_SEP foreign${C_0} 198.51.100.7"
  ui_box_bottom
}

demo_domains_status() {
  local d n=0
  ui_box_top "Routed hosts"
  while IFS= read -r d; do
    n=$((n + 1))
    ui_safe d "$d" $((UI_W - 12))
    ui_box_row "${C_DIM}$n.${C_0} $d"
  done <"$DEMO_DIR/domains"
  if ((n == 0)); then ui_box_row "${C_DIM}(empty)${C_0}"; fi
  ui_box_bottom
}

# ---------------------------------------------------------------- actions ----------------------
demo_health() {  # runs in the main shell (call:) so it can refresh the probe cache
  ui_blank
  probe_refresh 1
  ui_rule "Health check"
  probe_report
  ui_blank
}

demo_domain_add() {
  local h
  prompt_hostname h "Hostname to add (e.g. bard.google.com)" || act_cancel
  if grep -qxF -- "$h" "$DEMO_DIR/domains"; then
    ui_ok "$h is already in the list"
    return 0
  fi
  confirm "Add $h?" y || act_cancel
  act_step "Updating the list"
  act_do "add $h to the list" bash -c 'printf "%s\n" "$1" >>"$2"' _ "$h" "$DEMO_DIR/domains"
}

demo_domain_remove() {
  local -a list=()
  local pick
  mapfile -t list <"$DEMO_DIR/domains"
  if ((${#list[@]} == 0)); then act_cancel "the list is empty"; fi
  prompt_choice pick "Remove which host (number or name)" "" "${list[@]}" || act_cancel
  confirm "Remove $pick?" n || act_cancel
  act_step "Updating the list"
  act_do "remove $pick from the list" demo_domains_without "$pick"
}

demo_service_start() {
  act_step "Starting xray-gemini"
  act_do "start the relay" bash -c 'sleep 0.4; echo running >"$1"' _ "$DEMO_DIR/service"
}
demo_service_stop() {
  confirm "Stop the relay? Gemini requests pause while it is down." n || act_cancel
  act_step "Stopping xray-gemini"
  act_do "stop the relay" bash -c 'sleep 0.4; echo stopped >"$1"' _ "$DEMO_DIR/service"
}
demo_can_start() { [[ $(<"$DEMO_DIR/service") == stopped ]] || { MENU_WHY="already running"; return 1; }; }
demo_can_stop()  { [[ $(<"$DEMO_DIR/service") == running ]] || { MENU_WHY="not running"; return 1; }; }

demo_setup() {  # a wizard: every prompt re-asks on a typo and b cancels cleanly
  local fip port ver url
  ui_say "This walks through the prompts a real setup needs. Try typing nonsense, or just Enter."
  prompt_ipv4 fip "Foreign server IPv4" || act_cancel
  prompt_port port "Relay port" 20443 || act_cancel
  prompt_choice ver "Xray version" latest latest 26.3.27 25.12.1 || act_cancel
  prompt_secret url "Shecan registration URL" || act_cancel
  ui_info "foreign=$fip  port=$port  xray=$ver  url=(hidden, ${#url} characters)"
  confirm "Apply this configuration?" y || act_cancel
  act_step "Writing the configuration"
  act_do "write the config for $fip:$port" sleep 0.4
  act_commit                                   # step 1 is durable from here on
  act_step "Starting the relay"
  act_do "start the relay" sleep 0.4
  if [[ $port == 666 ]]; then                  # simulated failure: shows the PARTIAL report
    act_partial "configuration written for $fip:$port"
    act_fail "port 666 is refused by this demo"
  fi
}

demo_scope() {  # pick_many: b cancels and leaves the selection untouched
  local -a labels=("in-8443  :8443  Phone (vless)" "in-2053  :2053  Laptop (trojan)" "in-443  :443  Family (vless)")
  local -a sel=(1 1 0) chosen=()
  pick_many chosen "Which inbounds use the relay" labels sel || act_cancel
  ui_ok "selected: ${chosen[*]:-none}  (0-based indexes)"
}

demo_slow() {
  act_defer ui_note "cleanup ran (deferred)"
  act_step "A long operation - press Ctrl-C to stop it"
  ui_task "Waiting for a slow server" sleep 6
}

demo_fail() {
  act_step "Step one (will be rolled back)"
  act_on_fail ui_note "rollback: step one undone"
  ui_ok "step one done"
  act_step "Step two (fails)"
  must ls /nonexistent-directory-for-the-demo
  ui_ok "never reached: a failing step stops the operation"
}

demo_danger() {
  confirm_typed_force "This would delete everything the demo manages." yes || act_cancel
  act_step "Deleting"
  act_do "delete everything (pretend)" sleep 0.4
}

# ---------------------------------------------------------------- screens ----------------------
demo_screens() {
  menu_screen main "Demo relay" demo_status
  menu_item main 1 "Health check"      "live checks with what to do"  call:demo_health
  menu_item main 2 "Domains"           "edit the routed hosts"        screen:domains
  menu_item main 3 "Service"           "start / stop the relay"       screen:service
  menu_item main 4 "Setup wizard"      "validated prompts"            action:demo_setup
  menu_item main 5 "Choose inbounds"   "multi-select"                 action:demo_scope
  menu_item main 6 "Slow operation"    "try Ctrl-C while it runs"     action:demo_slow
  menu_item main 7 "Failing operation" "rollback + FAILED result"     action:demo_fail

  menu_screen domains "Domains" demo_domains_status
  menu_item domains 1 "Add a hostname"    "" action:demo_domain_add
  menu_item domains 2 "Remove a hostname" "" action:demo_domain_remove

  menu_screen service "Service"
  menu_item service 1 "Start relay" "" action:demo_service_start demo_can_start
  menu_item service 2 "Stop relay"  "" action:demo_service_stop demo_can_stop
  menu_item service 3 "Danger zone" "typed confirmation" action:demo_danger
}

demo_usage() {
  cat <<EOF
$GM_APP demo (Phase 1 foundation)   version $GM_VERSION
  --dry-run     actions only describe what they would do
  --yes         auto-accept plain y/n confirmations
  --ascii       plain ASCII frames      --no-color   no colours
  --status      print the status card once and exit
  -h, --help    this text
EOF
}

main() {
  local status_only=0
  while (($#)); do
    case $1 in
      --dry-run) GM_DRY=1 ;;
      --yes | -y) GM_YES=1 ;;
      --ascii) GM_ASCII=1 ;;
      --no-color) GM_COLOR=0 ;;
      --status) status_only=1 ;;
      -h | --help) demo_usage; return 0 ;;
      *) echo "unknown option: $1 (see --help)" >&2; return 2 ;;
    esac
    shift
  done
  gm_tmp_init
  gm_install_traps
  ui_detect
  in_init
  demo_seed
  probe_register relay probe_relay "Relay service"
  probe_register routing probe_routing "Gemini routing"
  probe_register dns probe_dns "Shecan DNS hijack"
  probe_register fw probe_fw "Firewall rule"
  demo_screens

  if ((status_only)); then
    demo_status
    return 0
  fi
  if ((!IN_OK)); then
    ui_err "no terminal available: run this from an interactive shell"
    return 1
  fi
  ui_banner "GEMINI $G_DOT SHECAN" "Phase 1 foundation demo $G_DOT v$GM_VERSION"
  menu_run main        # its own statement (never after || / if): see 40-action.sh
  ui_blank
  ui_note "bye"
  return 0
}

# Run when executed, or when piped into bash (curl ... | bash); stay quiet when sourced by tests.
if [[ -z ${BASH_SOURCE[0]:-} || ${BASH_SOURCE[0]} == "$0" ]]; then
  main "$@"
  exit $?
fi
